package builder_test

// PatientBuilder must produce the same payload as PayloadBuilderPatient in the PHP SDK. The golden
// file is generated by the PHP builder (see the commit message for the exact script), so a
// divergence in element names, nesting or value types fails here instead of in a downstream
// integration.

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"testing"

	"github.com/ivanwilliammd/satusehat-integration-go/v4/src/builder"
	"github.com/ivanwilliammd/satusehat-integration-go/v4/src/datatype"
)

func str(s string) *string { return &s }

func ptr[T any](v T) *T { return &v }

func phone() *datatype.ContactPoint {
	return &datatype.ContactPoint{
		System: ptr(datatype.ContactPointSystemPhone),
		Value:  str("+6281234567890"),
		Use:    ptr(datatype.ContactPointUseMobile),
	}
}

func TestPatientMatchesPhpBuilderPayload(t *testing.T) {
	isi, err := os.ReadFile(filepath.Join("testdata", "patient_php_golden.json"))
	if err != nil {
		t.Fatalf("golden hilang: %v", err)
	}

	var harapan map[string]interface{}
	if err := json.Unmarshal(isi, &harapan); err != nil {
		t.Fatalf("golden tidak sah: %v", err)
	}

	b := builder.NewPatientBuilder()
	b.SetMetaProfile("https://fhir.kemkes.go.id/r4/StructureDefinition/Patient")
	b.SetId("1000000001")
	b.AddIdentifier(&datatype.Identifier{System: "https://fhir.kemkes.go.id/id/nik", Value: "3171234567890001"})
	b.SetActive(true)
	b.AddName(&datatype.HumanName{Use: ptr(datatype.HumanNameUseOfficial), Text: "Budi Santoso", Family: "Santoso", Given: []string{"Budi"}})
	b.SetGender("male")
	b.SetBirthDate("1990-01-31")
	b.AddTelecom(phone())
	addr := &datatype.Address{Use: str("home"), City: str("Jakarta"), Country: str("ID"), Line: []string{"Jl. Contoh No. 1"}}
	b.AddAddress(addr)
	b.SetMaritalStatus(&datatype.CodeableConcept{Coding: []datatype.Coding{{
		System:  "http://terminology.hl7.org/CodeSystem/v3-MaritalStatus",
		Code:    "M",
		Display: "Married",
	}}})
	b.AddCommunication(&datatype.CodeableConcept{Coding: []datatype.Coding{{
		System:  "urn:ietf:bcp:47",
		Code:    "id-ID",
		Display: "Indonesian",
	}}}, true)
	b.AddExtension("https://fhir.kemkes.go.id/r4/StructureDefinition/patient-mother", "1000000002", "String")

	mentah, err := b.BuildJSON()
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}

	var dapat map[string]interface{}
	if err := json.Unmarshal(mentah, &dapat); err != nil {
		t.Fatalf("hasil bukan JSON sah: %v", err)
	}

	if !reflect.DeepEqual(harapan, dapat) {
		h, _ := json.MarshalIndent(harapan, "", "  ")
		d, _ := json.MarshalIndent(dapat, "", "  ")
		t.Fatalf("payload Go berbeda dari PHP\n--- PHP ---\n%s\n--- Go ---\n%s", h, d)
	}
}
